// LLM-driven conversation compaction — replaces programmatic XML summary
// with structured 9-section summary generated by a lightweight model.
//
// Multi-provider via Anthropic SDK (both MiniMax and DeepSeek support it):
//   MiniMax-* → https://api.minimaxi.com/anthropic
//   deepseek-* → https://api.deepseek.com/anthropic
//
// Based on Claude Code's services/compact/prompt.ts + compact.ts patterns:
//   - 9-section structured output format (adapted for customer service)
//   - Chain-of-thought stripping: <analysis> discarded, <summary> kept
//   - Falls back to programmatic buildCompactionSummary on error

import type { Message, MemoryStrategy } from '@intera/shared/types'
import { DEFAULT_MEMORY_MODEL } from '@intera/shared/memory/contract'
import { withRetry, CannotRetryError } from './api/with-retry'
import { getProviderConfig, createAgentClient } from './api/provider-config'
import { CASE_COMPACT_PROMPT } from './case-compact-prompt'
import { PROFILE_COMPACT_PROMPT } from './profile-compact-prompt'

/**
 * @deprecated Replaced by CASE_COMPACT_PROMPT (intra-case) and
 * PROFILE_COMPACT_PROMPT (cross-chat profile). Kept for backward
 * compatibility with custom compactPrompt overrides in MemoryStrategy.
 */
export const COMPACT_SYSTEM_PROMPT = CASE_COMPACT_PROMPT

/** Clean up compact output — strip any leftover tags, trim whitespace. */
export function formatCompactSummary(raw: string): string {
  return raw
    .replace(/<analysis>[\s\S]*?<\/analysis>/gi, '')
    .replace(/<think>[\s\S]*?<\/think>/gi, '')
    .replace(/<\/?summary>/gi, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim()
}

export interface CompactConversationResult {
  summary: string | null
  model: string
  provider: string
  tokensUsed?: number
  error?: string
}

/**
 * Call a lightweight model to generate a structured conversation summary.
 * Both MiniMax and DeepSeek support Anthropic-compatible API endpoints, so
 * all providers use the Anthropic SDK with different baseURL/apiKey.
 *
 * Falls back to returning null on error — caller should use programmatic fallback.
 */
export async function compactConversation(
  messages: Message[],
  strategy: MemoryStrategy,
  opts?: { purpose?: 'case' | 'profile' },
): Promise<CompactConversationResult> {
  const purpose = opts?.purpose ?? 'case'
  const model =
    purpose === 'profile'
      ? (strategy.profileModel || strategy.compactModel || DEFAULT_MEMORY_MODEL)
      : (strategy.compactModel || DEFAULT_MEMORY_MODEL)
  const { apiKey, baseURL, provider } = getProviderConfig(model)

  if (!apiKey) {
    return { summary: null, model, provider, error: `API key not configured for ${provider}` }
  }

  const defaultPrompt =
    purpose === 'profile' ? PROFILE_COMPACT_PROMPT : CASE_COMPACT_PROMPT
  const systemPrompt = strategy.compactPrompt || defaultPrompt

  const apiMessages = messages
    .filter((m) => typeof m.content === 'string' && m.content.trim().length > 0)
    .map((m) => ({
      role: m.role === 'user' ? 'user' as const : 'assistant' as const,
      content: m.content as string,
    }))
    .slice(-(strategy.compactMaxMessages || 20))

  try {
    const client = createAgentClient(model)

    const response = await withRetry(
      (retryClient, ctx) => retryClient.messages.create({
        model: ctx.model,
        max_tokens: Math.min(strategy.l2SummaryMaxTokens, strategy.compactMaxTokensCap),
        system: systemPrompt,
        messages: apiMessages,
        temperature: strategy.compactTemperature,
        thinking: { type: 'disabled' as const },
      }),
      { querySource: 'compact', model },
      () => createAgentClient(model),
    )

    const rawText = response.content
      .filter((block) => block.type === 'text')
      .map((block) => (block as { type: 'text'; text: string }).text)
      .join('')

    if (!rawText) {
      return { summary: null, model, provider, error: 'Empty response' }
    }

    const summary = formatCompactSummary(rawText)
    if (!summary || summary.length < Math.min(strategy.compactMinSummaryLength, 10)) {
      return { summary: null, model, provider, error: 'Summary too short' }
    }

    return {
      summary,
      model,
      provider,
      tokensUsed: response.usage?.input_tokens
        ? response.usage.input_tokens + (response.usage.output_tokens || 0)
        : undefined,
    }
  } catch (err) {
    const errorMsg = err instanceof Error ? err.message : 'Unknown error'
    console.warn(`[Compact] ${provider} call failed (${model}):`, errorMsg)
    return { summary: null, model, provider, error: errorMsg }
  }
}

/**
 * Context collapse: persists a compressed snapshot of the conversation
 * to the CaseMemory.summary field, allowing the agent to restore context
 * across restarts without keeping all messages in memory.
 */
export async function contextCollapse(
  messages: Message[],
  memoryStrategy: import('@intera/shared/types').MemoryStrategy,
  caseId: string,
): Promise<string | null> {
  if (messages.length < 6) return null // not enough context to collapse
  const result = await compactConversation(messages, memoryStrategy)
  return result.summary
}

/**
 * Reactive compact: emergency trim when context overflows (413 error).
 * Keeps only the last N messages plus system prompt.
 */
export function reactiveCompact(messages: Message[], keepLast: number = 4): Message[] {
  if (messages.length <= keepLast) return messages
  const systemMsgs = messages.filter((m) => m.role === 'system')
  const recentMsgs = messages.slice(-keepLast)
  return [...systemMsgs, ...recentMsgs]
}
